INSERT INTO shiori_days (id, shiori_id, trip_date, day_number, title, notes, estimated_cost, is_editable, is_comment_open, created_at, updated_at) VALUES
('33333333-3333-3333-3333-000000000001', '22222222-2222-2222-2222-000000000001', '2026-10-15', 1, '日本橋出発・横浜港', E'07:30 日本橋集合。レンタカー2台で出発\n横浜は歩き多いのでスニーカー推奨\n中華街は12時前後が狙い目\nみなとみらいは夕方からがきれい\n夜はホテル近くで軽く飲む\n翌朝は早め出発', NULL, true, true, '2026-09-01 10:00:00+09', '2026-09-01 10:00:00+09'),
('33333333-3333-3333-3333-000000000002', '22222222-2222-2222-2222-000000000001', '2026-10-16', 2, '箱根・三島', E'箱根は週末混むので芦ノ湖は午前中に\n山上は寒いので羽織り1枚\n三島コロッケは駅近くの有名店へ\n旧東海道の石畳は靴底すり減る注意\n宿は三島駅前で荷物を先に\n翌日は静岡方面へ南下', NULL, true, true, '2026-09-01 10:00:00+09', '2026-09-01 10:00:00+09'),
('33333333-3333-3333-3333-000000000003', '22222222-2222-2222-2222-000000000001', '2026-10-17', 3, '静岡・浜松', E'茶畑は展望台からパノラマ撮影\n静岡駅でお茶とお土産用煎茶\n浜名湖はパラシュート体験予約済\n浜松城は階段きつい・水分多め\nうなぎは夜メインで昼は軽め\n翌朝は名古屋経由で京都へ', NULL, true, true, '2026-09-01 10:00:00+09', '2026-09-01 10:00:00+09'),
('33333333-3333-3333-3333-000000000004', '22222222-2222-2222-2222-000000000001', '2026-10-18', 4, '名古屋寄り道・京都到着', E'熱田神宮は朝イチが空いている\n名古屋めしは味噌カツで腹八分\n京都入りは午後、伏見稲荷から\n祇園は夕方の散策がおすすめ\nお土産は京都駅でまとめ買い\n解散後は各自新幹線で帰路', NULL, true, true, '2026-09-01 10:00:00+09', '2026-09-01 10:00:00+09');
